const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat, HeadingLevel,
  TabStopType, TabStopPosition
} = require('docx');

// Color palette: deep navy accent, charcoal body
const NAVY = "1F3A5F";
const CHARCOAL = "2B2B2B";
const LIGHT_GRAY = "6B6B6B";
const DIVIDER = "1F3A5F";

// Reusable divider paragraph (thin navy rule)
const divider = () => new Paragraph({
  spacing: { before: 60, after: 120 },
  border: {
    bottom: { style: BorderStyle.SINGLE, size: 8, color: DIVIDER, space: 1 }
  },
  children: [new TextRun({ text: "" })]
});

// Section heading
const sectionHeading = (text) => new Paragraph({
  spacing: { before: 240, after: 80 },
  children: [new TextRun({
    text: text.toUpperCase(),
    bold: true,
    size: 24, // 12pt
    color: NAVY,
    font: "Calibri",
    characterSpacing: 40
  })],
  border: {
    bottom: { style: BorderStyle.SINGLE, size: 6, color: NAVY, space: 2 }
  }
});

// Job title + company row (using tab stops to right-align dates)
const jobHeader = (title, company, location, dates) => [
  new Paragraph({
    spacing: { before: 160, after: 0 },
    tabStops: [{ type: TabStopType.RIGHT, position: 9360 }],
    children: [
      new TextRun({ text: title, bold: true, size: 23, color: CHARCOAL, font: "Calibri" }),
      new TextRun({ text: "\t", size: 22 }),
      new TextRun({ text: dates, size: 20, color: LIGHT_GRAY, italics: true, font: "Calibri" })
    ]
  }),
  new Paragraph({
    spacing: { before: 20, after: 60 },
    children: [
      new TextRun({ text: `${company}`, size: 22, color: NAVY, font: "Calibri", bold: true }),
      new TextRun({ text: `  |  ${location}`, size: 20, color: LIGHT_GRAY, font: "Calibri" })
    ]
  })
];

// Bullet point for achievements
const bullet = (text, boldStart) => {
  const runs = [];
  if (boldStart) {
    runs.push(new TextRun({ text: boldStart, bold: true, size: 22, color: CHARCOAL, font: "Calibri" }));
    runs.push(new TextRun({ text: text, size: 22, color: CHARCOAL, font: "Calibri" }));
  } else {
    runs.push(new TextRun({ text: text, size: 22, color: CHARCOAL, font: "Calibri" }));
  }
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 40, after: 40, line: 280 },
    children: runs
  });
};

// Summary paragraph
const summaryPara = (text) => new Paragraph({
  spacing: { before: 80, after: 80, line: 300 },
  alignment: AlignmentType.JUSTIFIED,
  children: [new TextRun({ text, size: 22, color: CHARCOAL, font: "Calibri" })]
});

// Skills grid (2-column table)
const skillsTable = (skills) => {
  const half = Math.ceil(skills.length / 2);
  const col1 = skills.slice(0, half);
  const col2 = skills.slice(half);
  const rows = [];
  const maxRows = Math.max(col1.length, col2.length);

  for (let i = 0; i < maxRows; i++) {
    rows.push(new TableRow({
      children: [
        new TableCell({
          borders: {
            top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" }
          },
          width: { size: 4680, type: WidthType.DXA },
          margins: { top: 40, bottom: 40, left: 60, right: 60 },
          children: [new Paragraph({
            children: col1[i] ? [
              new TextRun({ text: "▸ ", bold: true, color: NAVY, size: 22, font: "Calibri" }),
              new TextRun({ text: col1[i], size: 22, color: CHARCOAL, font: "Calibri" })
            ] : [new TextRun({ text: "" })]
          })]
        }),
        new TableCell({
          borders: {
            top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" }
          },
          width: { size: 4680, type: WidthType.DXA },
          margins: { top: 40, bottom: 40, left: 60, right: 60 },
          children: [new Paragraph({
            children: col2[i] ? [
              new TextRun({ text: "▸ ", bold: true, color: NAVY, size: 22, font: "Calibri" }),
              new TextRun({ text: col2[i], size: 22, color: CHARCOAL, font: "Calibri" })
            ] : [new TextRun({ text: "" })]
          })]
        })
      ]
    }));
  }

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows
  });
};

// ============== HEADER ==============
const headerName = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 60 },
  children: [new TextRun({
    text: "MIRANDA SCHROEDER",
    bold: true,
    size: 52, // 26pt
    color: NAVY,
    font: "Calibri",
    characterSpacing: 80
  })]
});

const headerTitle = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 120 },
  children: [new TextRun({
    text: "Retail Sales Leader  |  Kitchen & Bath Design Professional  |  Team Builder",
    size: 22,
    color: CHARCOAL,
    italics: true,
    font: "Calibri"
  })]
});

const headerContact = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 0 },
  children: [
    new TextRun({ text: "Franklin, TN 37067", size: 20, color: LIGHT_GRAY, font: "Calibri" }),
    new TextRun({ text: "   |   ", size: 20, color: NAVY, font: "Calibri", bold: true }),
    new TextRun({ text: "(916) 300-0577", size: 20, color: LIGHT_GRAY, font: "Calibri" }),
    new TextRun({ text: "   |   ", size: 20, color: NAVY, font: "Calibri", bold: true }),
    new TextRun({ text: "mschroeder4584@outlook.com", size: 20, color: LIGHT_GRAY, font: "Calibri" }),
    new TextRun({ text: "   |   ", size: 20, color: NAVY, font: "Calibri", bold: true }),
    new TextRun({ text: "Open to Relocation", size: 20, color: LIGHT_GRAY, italics: true, font: "Calibri" })
  ]
});

// ============== SUMMARY ==============
const summaryContent = [
  sectionHeading("Professional Summary"),
  summaryPara("Results-driven retail leader with over a decade of experience in high-volume showroom sales, custom design, and team development across the kitchen and bath, flooring, and home furnishings industries. Proven track record of exceeding sales targets, coaching high-performing teams, and delivering exceptional customer experiences from first consultation through final installation. Skilled in translating customer vision into precision-engineered designs using 2020 Design software, building vendor partnerships, and driving showroom profitability through operational excellence. Known for a consultative sales approach, service recovery instincts, and the ability to elevate team close rates while maintaining brand standards."),
];

// ============== CORE COMPETENCIES ==============
const skills = [
  "Showroom Sales Leadership",
  "Custom Kitchen & Bath Design",
  "Team Coaching & Performance Reviews",
  "2020 Design Software (CAD)",
  "Sales Pipeline & Lead Conversion",
  "Vendor & Contractor Partnerships",
  "Customer Experience Management",
  "Operational & Inventory Oversight",
  "Consultative Selling & Closing",
  "Product Demonstrations",
  "Project Scheduling & Coordination",
  "Service Recovery & Retention"
];

const competenciesContent = [
  sectionHeading("Core Competencies"),
  skillsTable(skills)
];

// ============== EXPERIENCE ==============
const experienceContent = [
  sectionHeading("Professional Experience"),

  ...jobHeader("Store Manager & Lead Designer", "Cabinets To Go", "Franklin, TN", "May 2021 to Present"),
  bullet("daily operations of a high-volume kitchen and bath showroom, driving consistent sales growth, customer satisfaction, and team performance in a competitive Middle Tennessee market.", "Lead "),
  bullet("coach, and evaluate designers and sales staff through regular performance reviews, elevating close rates, design accuracy, and overall showroom productivity.", "Manage, "),
  bullet("the full customer journey from lead generation and in-home consultation through order processing, delivery coordination, and post-installation support.", "Own "),
  bullet("customized kitchen and cabinetry layouts using 2020 Design software, balancing aesthetics, functionality, and budget to deliver solutions clients trust.", "Produce "),
  bullet("sales metrics, conversion rates, and team goals to consistently meet and exceed monthly targets while identifying opportunities for performance lift.", "Track "),
  bullet("with countertop fabricators, builders, and vendor partners to ensure seamless project execution, accurate timelines, and high-quality installations.", "Partner "),
  bullet("inventory accuracy, showroom presentation, and operational standards to uphold a polished, high-performing retail environment.", "Maintain "),
  bullet("complex customer concerns with a focus on service recovery, repeat business, and long-term client relationships.", "Resolve "),

  ...jobHeader("Sales Representative, Sleep Expert & Key Holder", "DSG - Ashley HomeStore", "Brentwood, TN", "July 2019 to June 2021"),
  bullet("a consultative sales approach across mattress and home furnishings categories, guiding guests through tailored product demonstrations to match lifestyle and budget needs.", "Delivered "),
  bullet("opening, closing, and key-holder responsibilities, demonstrating early leadership and trust from store management.", "Held "),
  bullet("strong product knowledge across multiple categories and used it to build credibility, answer technical questions, and close sales.", "Developed "),
  bullet("team members on merchandising, client engagement, and back-of-house workflows, contributing to a cohesive sales floor.", "Supported "),
  bullet("phone etiquette, follow-up discipline, and CRM tools to nurture leads and convert walk-ins into long-term customers.", "Leveraged "),

  ...jobHeader("Flooring Sales Associate", "RC Willey Home Furnishings", "Rocklin, CA", "November 2017 to July 2019"),
  bullet("Top Sales, 3rd Quarter 2018 and 2nd Place Top Sales for the Year 2018, out of a competitive multi-store sales team.", "Recognized as "),
  bullet("customers through the flooring selection process, uncovering needs, presenting options, and guiding decisions from quote to installation.", "Consulted "),
  bullet("consistent, high-touch follow-up throughout every stage of the sales process to ensure satisfaction and drive referrals.", "Delivered "),
  bullet("product knowledge across hardwood, tile, carpet, and specialty flooring to confidently recommend the right solution for each space.", "Maintained "),

  ...jobHeader("Spa Receptionist", "Monterey Plaza Hotel & Spa", "Monterey, CA", "July 2017 to October 2017"),
  bullet("the front desk of a four-star luxury spa, managing guest bookings, phone inquiries, and VIP tours with polish and discretion.", "Anchored "),
  bullet("cash handling, retail restocking, and daily cleanliness standards to protect the guest experience and brand presentation.", "Handled "),

  ...jobHeader("Flooring & Décor Specialist, Head Cashier & Paint Associate", "The Home Depot", "Seaside, CA", "March 2015 to June 2017"),
  bullet("a team of cashiers, managing breaks, scheduling support, register setup, and equipment troubleshooting across high-traffic shifts.", "Supervised "),
  bullet("with outside vendors and installation partners to finalize flooring, paint, and décor orders end-to-end.", "Coordinated "),
  bullet("full knowledge of buying, installation, and store procedures to support customers across three specialty departments.", "Mastered "),
  bullet("cash handling, open and close procedures, and work statistics reporting with accuracy and accountability.", "Owned "),

  ...jobHeader("Cashier & Customer Service Specialist", "Whole Foods Market", "Monterey, CA", "August 2013 to October 2014"),
  bullet("a gold-standard customer experience on every interaction, earning a reputation for attentive, personable service in a demanding retail environment.", "Delivered "),
  bullet("supervisors during peak hours to control customer flow, reduce wait times, and keep front-end operations running smoothly.", "Assisted "),
  bullet("and exceeded regional cashier variance standards while upholding all cash handling, compliance, and sanitation procedures.", "Met "),
  bullet("to regional and global store programs while supporting pricing accuracy, signage integrity, and departmental cleanliness.", "Contributed "),
];

// ============== EDUCATION ==============
const educationContent = [
  sectionHeading("Education"),
  new Paragraph({
    spacing: { before: 80, after: 40 },
    tabStops: [{ type: TabStopType.RIGHT, position: 9360 }],
    children: [
      new TextRun({ text: "High School Diploma", bold: true, size: 22, color: CHARCOAL, font: "Calibri" }),
      new TextRun({ text: "\t", size: 22 }),
      new TextRun({ text: "August 2008 to June 2012", size: 20, color: LIGHT_GRAY, italics: true, font: "Calibri" })
    ]
  }),
  new Paragraph({
    spacing: { before: 0, after: 80 },
    children: [
      new TextRun({ text: "Lincoln High School", size: 22, color: NAVY, bold: true, font: "Calibri" }),
      new TextRun({ text: "  |  Lincoln, CA", size: 20, color: LIGHT_GRAY, font: "Calibri" })
    ]
  })
