  bullet("Top Flooring Sales, 3rd Quarter 2018 — RC Willey Home Furnishings", null),
  bullet("Top Sales for the Year, 2nd Place (2018) — RC Willey Home Furnishings", null),
];

// ============== DOCUMENT ==============
const doc = new Document({
  creator: "Miranda Schroeder",
  title: "Miranda Schroeder - Resume",
  styles: {
    default: { document: { run: { font: "Calibri", size: 22 } } }
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0,
          format: LevelFormat.BULLET,
          text: "•",
          alignment: AlignmentType.LEFT,
          style: {
            paragraph: { indent: { left: 360, hanging: 200 } },
            run: { color: NAVY, bold: true }
          }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 }
      }
    },
    children: [
      headerName,
      headerTitle,
      headerContact,
      divider(),
      ...summaryContent,
      ...competenciesContent,
      ...experienceContent,
      ...educationContent,
      ...awardsContent,
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Miranda_Schroeder_Resume.docx", buffer);
  console.log("Resume created successfully");
});

