const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat, HeadingLevel,
  TabStopType, TabStopPosition
} = require('docx');

const NAVY = "1F3A5F";
const CHARCOAL = "2B2B2B";
const LIGHT_GRAY = "6B6B6B";

const divider = () => new Paragraph({
  spacing: { before: 60, after: 80 },
  border: {
    bottom: { style: BorderStyle.SINGLE, size: 8, color: NAVY, space: 1 }
  },
  children: [new TextRun({ text: "" })]
});

const sectionHeading = (text) => new Paragraph({
  spacing: { before: 140, after: 40 },
  children: [new TextRun({
    text: text.toUpperCase(),
    bold: true,
    size: 24,
    color: NAVY,
    font: "Calibri",
    characterSpacing: 40
  })],
  border: {
    bottom: { style: BorderStyle.SINGLE, size: 6, color: NAVY, space: 2 }
  }
});

const jobHeader = (title, company, location, dates) => [
  new Paragraph({
    spacing: { before: 100, after: 0 },
    tabStops: [{ type: TabStopType.RIGHT, position: 10080 }],
    children: [
      new TextRun({ text: title, bold: true, size: 23, color: CHARCOAL, font: "Calibri" }),
      new TextRun({ text: "\t", size: 22 }),
      new TextRun({ text: dates, size: 20, color: LIGHT_GRAY, italics: true, font: "Calibri" })
    ]
  }),
  new Paragraph({
    spacing: { before: 20, after: 40 },
    children: [
      new TextRun({ text: `${company}`, size: 22, color: NAVY, font: "Calibri", bold: true }),
      new TextRun({ text: `  |  ${location}`, size: 20, color: LIGHT_GRAY, font: "Calibri" })
    ]
  })
];

const bullet = (leadWord, rest) => {
  const runs = [
    new TextRun({ text: leadWord, bold: true, size: 22, color: CHARCOAL, font: "Calibri" }),
    new TextRun({ text: rest, size: 22, color: CHARCOAL, font: "Calibri" })
  ];
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 20, after: 20, line: 260 },
    children: runs
  });
};

const plainBullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 20, after: 20, line: 260 },
  children: [new TextRun({ text, size: 22, color: CHARCOAL, font: "Calibri" })]
});

const summaryPara = (text) => new Paragraph({
  spacing: { before: 40, after: 40, line: 280 },
  alignment: AlignmentType.JUSTIFIED,
  children: [new TextRun({ text, size: 22, color: CHARCOAL, font: "Calibri" })]
});

const skillsTable = (skills) => {
  const half = Math.ceil(skills.length / 2);
  const col1 = skills.slice(0, half);
  const col2 = skills.slice(half);
  const rows = [];
  const maxRows = Math.max(col1.length, col2.length);

  for (let i = 0; i < maxRows; i++) {
    rows.push(new TableRow({
      children: [
        new TableCell({
          borders: {
            top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" }
          },
          width: { size: 5040, type: WidthType.DXA },
          margins: { top: 30, bottom: 30, left: 60, right: 60 },
          children: [new Paragraph({
            children: col1[i] ? [
              new TextRun({ text: "▸ ", bold: true, color: NAVY, size: 22, font: "Calibri" }),
              new TextRun({ text: col1[i], size: 22, color: CHARCOAL, font: "Calibri" })
            ] : [new TextRun({ text: "" })]
          })]
        }),
        new TableCell({
          borders: {
            top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" }
          },
          width: { size: 5040, type: WidthType.DXA },
          margins: { top: 30, bottom: 30, left: 60, right: 60 },
          children: [new Paragraph({
            children: col2[i] ? [
              new TextRun({ text: "▸ ", bold: true, color: NAVY, size: 22, font: "Calibri" }),
              new TextRun({ text: col2[i], size: 22, color: CHARCOAL, font: "Calibri" })
            ] : [new TextRun({ text: "" })]
          })]
        })
      ]
    }));
  }

  return new Table({
    width: { size: 10080, type: WidthType.DXA },
    columnWidths: [5040, 5040],
    rows
  });
};

// ============== HEADER ==============
const headerName = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 60 },
  children: [new TextRun({
    text: "MIRANDA SCHROEDER",
    bold: true,
    size: 52,
    color: NAVY,
    font: "Calibri",
    characterSpacing: 80
  })]
});

const headerTitle = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 100 },
  children: [new TextRun({
    text: "Retail Sales Leader  |  Kitchen & Bath Design Professional  |  Team Builder",
    size: 22,
    color: CHARCOAL,
    italics: true,
    font: "Calibri"
  })]
});

const headerContact = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 0 },
  children: [
    new TextRun({ text: "Franklin, TN 37067", size: 20, color: LIGHT_GRAY, font: "Calibri" }),
    new TextRun({ text: "   |   ", size: 20, color: NAVY, font: "Calibri", bold: true }),
    new TextRun({ text: "(916) 300-0577", size: 20, color: LIGHT_GRAY, font: "Calibri" }),
    new TextRun({ text: "   |   ", size: 20, color: NAVY, font: "Calibri", bold: true }),
    new TextRun({ text: "mschroeder4584@outlook.com", size: 20, color: LIGHT_GRAY, font: "Calibri" }),
    new TextRun({ text: "   |   ", size: 20, color: NAVY, font: "Calibri", bold: true }),
    new TextRun({ text: "Open to Relocation", size: 20, color: LIGHT_GRAY, italics: true, font: "Calibri" })
  ]
});

// ============== SUMMARY ==============
const summaryContent = [
  sectionHeading("Professional Summary"),
  summaryPara("Top-performing retail leader with 10+ years of success driving revenue growth, team performance, and customer loyalty in high-volume showroom environments. Consistently ranks among top sales producers, turns underperforming teams into goal-crushing units, and designs custom kitchen and bath solutions that close at premium ticket sizes. Known for a consultative, relationship-first sales approach, sharp design instincts in 2020 Design software, and the operational discipline to run a profitable showroom from lead to install. A coach, closer, and builder who owns the number and delivers it."),
];

// ============== CORE COMPETENCIES ==============
const skills = [
  "High-Volume Showroom Leadership",
  "Custom Kitchen & Bath Design",
  "Team Coaching & Close-Rate Growth",
  "2020 Design Software (CAD)",
  "Consultative Selling & Closing",
  "P&L, KPIs & Sales Forecasting",
  "Lead Generation & Pipeline Management",
  "Vendor, Builder & Trade Partnerships",
  "Customer Experience & Retention",
  "Inventory & Operational Excellence"
];

const competenciesContent = [
  sectionHeading("Core Competencies"),
  skillsTable(skills)
];

// ============== EXPERIENCE ==============
const experienceContent = [
  sectionHeading("Professional Experience"),

  ...jobHeader("Store Manager & Lead Designer", "Cabinets To Go", "Franklin, TN", "May 2021 to Present"),
  bullet("Lead ", "day-to-day operations of a high-volume kitchen and bath showroom in the competitive Middle Tennessee market, consistently hitting and exceeding monthly revenue targets."),
  bullet("Built and coach ", "a high-performing design and sales team, driving measurable gains in close rate, average ticket, and customer satisfaction through structured training, live coaching, and performance reviews."),
  bullet("Design ", "custom kitchen and cabinetry solutions in 2020 Design software that convert at premium price points, ranging from single-room remodels to full home builds."),
  bullet("Own ", "the full customer journey from lead capture and in-home consultation through order, delivery, and post-install support, earning repeat business and referral volume from builders, designers, and homeowners."),
  bullet("Manage ", "showroom inventory, vendor relationships, and project timelines with countertop fabricators, installers, and trade partners to protect margin and deliver clean, on-time installs."),
  bullet("Turn ", "escalated customer situations into long-term loyalty through disciplined service recovery, protecting store reputation and generating recurring revenue."),

  ...jobHeader("Sales Representative, Sleep Expert & Key Holder", "DSG - Ashley HomeStore", "Brentwood, TN", "July 2019 to June 2021"),
  bullet("Ranked ", "among the top producers on the sales floor by pairing deep product expertise with a consultative, needs-based selling approach across mattress and home furnishings categories."),
  bullet("Trusted ", "with key-holder responsibility including opening, closing, cash reconciliation, and floor leadership, signaling early-career management potential."),
  bullet("Converted ", "walk-ins and cold leads into long-term customers through disciplined follow-up, strong phone etiquette, and consistent use of CRM tools."),
  bullet("Mentored ", "newer team members on product knowledge, guest engagement, and merchandising standards, lifting overall floor performance."),

  ...jobHeader("Flooring Sales Associate", "RC Willey Home Furnishings", "Rocklin, CA", "November 2017 to July 2019"),
  bullet("Earned ", "Top Sales 3rd Quarter 2018 and 2nd Place Top Sales for the Year 2018 against a competitive multi-store sales team, through high-trust customer relationships and a steady referral pipeline."),
  bullet("Guided ", "customers through the full flooring selection process across hardwood, tile, carpet, and specialty surfaces, pairing product expertise with in-home design sensibility to close larger tickets."),
  bullet("Delivered ", "proactive, white-glove follow-up from quote through installation, generating repeat business and word-of-mouth referrals."),

  ...jobHeader("Flooring & Décor Specialist, Head Cashier & Paint Associate", "The Home Depot", "Seaside, CA", "March 2015 to June 2017"),
  bullet("Led ", "front-end cashier operations during peak shifts, supervising staff, managing breaks, and resolving register issues to keep checkout flowing and customers moving."),
  bullet("Sold ", "across three specialty departments (flooring, paint, and décor), coordinating with outside vendors and install partners to finalize orders end-to-end."),
  bullet("Trusted ", "with cash handling, opening and closing procedures, and operational reporting, maintaining accuracy and accountability across high-traffic shifts."),

  ...jobHeader("Spa Receptionist", "Monterey Plaza Hotel & Spa", "Monterey, CA", "July 2017 to October 2017"),
  bullet("Anchored ", "the front desk of a four-star luxury spa, managing VIP bookings, tours, and guest experience with the polish expected of a top-tier hospitality brand."),

  ...jobHeader("Cashier & Customer Service Specialist", "Whole Foods Market", "Monterey, CA", "August 2013 to October 2014"),
  bullet("Delivered ", "the brand's signature premium guest experience on every interaction, consistently meeting regional cashier variance and compliance standards while supporting peak-hour flow."),
];

// ============== EDUCATION ==============
const educationContent = [
  sectionHeading("Education"),
  new Paragraph({
    spacing: { before: 40, after: 0 },
    children: [
      new TextRun({ text: "Associate of Arts in Business", bold: true, size: 22, color: CHARCOAL, font: "Calibri" })
    ]
  })
];

// ============== AWARDS ==============
const awardsContent = [
  sectionHeading("Awards & Recognition"),
  plainBullet("Top Flooring Sales, 3rd Quarter 2018  |  RC Willey Home Furnishings"),
  plainBullet("Top Sales for the Year, 2nd Place (2018)  |  RC Willey Home Furnishings"),
];

// ============== DOCUMENT ==============
const doc = new Document({
  creator: "Miranda Schroeder",
  title: "Miranda Schroeder - Resume",
  styles: {
    default: { document: { run: { font: "Calibri", size: 22 } } }
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0,
          format: LevelFormat.BULLET,
          text: "•",
          alignment: AlignmentType.LEFT,
          style: {
            paragraph: { indent: { left: 360, hanging: 200 } },
            run: { color: NAVY, bold: true }
          }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
      }
    },
    children: [
      headerName,
      headerTitle,
      headerContact,
      divider(),
      ...summaryContent,
      ...competenciesContent,
      ...experienceContent,
      ...educationContent,
      ...awardsContent,
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Miranda_Schroeder_Resume.docx", buffer);
  console.log("Resume created");
});

